-- C3-4: the Daily Approval Limit's ledger (plan §4.3, §6.2), written by
-- MoneyControlService.withinLimit inside each approving command's
-- transaction.
--
-- Generated by `prisma migrate dev --create-only`, then the hand-written
-- part appended below the line. `prisma migrate diff --from-config-datasource
-- --to-schema prisma/schema.prisma --script` prints an empty migration once
-- this is applied.

-- CreateTable
CREATE TABLE "ApprovalLedger" (
    "id" TEXT NOT NULL,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "businessDate" DATE NOT NULL,
    "staffId" TEXT NOT NULL,
    "amountKobo" INTEGER NOT NULL,
    "action" TEXT NOT NULL,
    "ref" TEXT,

    CONSTRAINT "ApprovalLedger_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE INDEX "ApprovalLedger_staffId_businessDate_idx" ON "ApprovalLedger"("staffId", "businessDate");

-- AddForeignKey
ALTER TABLE "ApprovalLedger" ADD CONSTRAINT "ApprovalLedger_staffId_fkey" FOREIGN KEY ("staffId") REFERENCES "Staff"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- ===========================================================================
-- Hand-written below: what Prisma cannot express.
-- ===========================================================================

-- A ledger row is an amount that counted. A zero or a negative would lower
-- a manager's total for the day, which is the one thing the limit must not
-- allow; refunds count by their size, so the writer stores the absolute
-- amount and never writes a row for nothing.
ALTER TABLE "ApprovalLedger"
  ADD CONSTRAINT "ApprovalLedger_amount_check" CHECK ("amountKobo" > 0);

-- The ledger is append-only, as the audit log is (A13): a row updated or
-- deleted is a manager's daily limit quietly raised. A row trigger refuses
-- UPDATE and DELETE, and a statement trigger refuses TRUNCATE, which
-- bypasses row triggers. The function is the ledger's own, so the error
-- names the table it protects. The table's owner can still drop the
-- trigger; that is a reviewed migration, not an accident.
CREATE FUNCTION "approval_ledger_append_only"() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'ApprovalLedger is append-only: % is not allowed', TG_OP
    USING ERRCODE = 'insufficient_privilege';
END;
$$;

CREATE TRIGGER "ApprovalLedger_append_only_row"
  BEFORE UPDATE OR DELETE ON "ApprovalLedger"
  FOR EACH ROW EXECUTE FUNCTION "approval_ledger_append_only"();

CREATE TRIGGER "ApprovalLedger_append_only_truncate"
  BEFORE TRUNCATE ON "ApprovalLedger"
  FOR EACH STATEMENT EXECUTE FUNCTION "approval_ledger_append_only"();
